{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Sound Bath Series — {{BUSINESS_NAME}}</title>
  <link rel="stylesheet" href="assets/css/styles.css" />
  <meta name="description" content="Practical sound experiences for clarity and rest in {{CITY}}, {{STATE}}. Series, private sessions, and tailored workshops." />
</head>
<body>
  <header class="site-header">
    <div class="wrap header-grid">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Sessions</a>
        <a href="/pricing.html">Rates</a>
        <a href="/about.html">Story</a>
        <a href="/faq.html">FAQ</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="/contact.html" class="muted">Connect</a>
      </nav>
      <button class="menu-toggle" aria-expanded="false">Menu</button>
    </div>
  </header>

  <main>
    <!-- Hero (sectionPack: hero) -->
    <section class="hero">
      <div class="pattern" aria-hidden="true"></div>
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>Sound journeys tuned for real life pauses</h1>
          <p class="lede">Short-form group sessions and private practices designed to help you notice, reset, and move forward with intention.</p>

          <div class="mood-method" data-cta-template="{{PRIMARY_CTA_URL}}?mood={id}" data-cta-base="{{PRIMARY_CTA_URL}}">
            <label for="mood-hero">How are you feeling right now?</label>
            <select id="mood-hero" class="mood-select">
              <option value="calm">A little off-balance</option>
              <option value="wired">Edgy or wired</option>
              <option value="foggy">Distracted or foggy</option>
              <option value="flat">Tired or flat</option>
              <option value="celebrate">Want to deepen</option>
            </select>

            <div class="method-card">
              <strong class="method-title">Recommended: Gentle Resonance</strong>
              <p class="method-desc">A guided laying-down session that uses long tones and breath cues to ease tension and invite clarity.</p>
            </div>

            <div class="mood-cta-row">
              <a href="{{PRIMARY_CTA_URL}}" class="primary-cta">{{PRIMARY_CTA_LABEL}}</a>
              <a href="/events.html" class="secondary">See upcoming gatherings</a>
            </div>
          </div>

        </div>

        <aside class="hero-aside">
          <div class="next-event">
            <div class="when">Next: Sat • 7pm</div>
            <h3>Evening Drift — Group Session</h3>
            <p class="meta">Acoustic bowls, chrome tongue, and guided breath. Limited mats available.</p>
            <a href="/events.html" class="small-cta">Reserve a spot</a>
          </div>

          <ul class="quick-stats">
            <li><strong>3</strong> Signature formats</li>
            <li><strong>25+</strong> community gatherings last year</li>
            <li><strong>Private</strong> one-to-one sessions</li>
          </ul>
        </aside>
      </div>
    </section>

    <!-- Myth vs Truth (sectionPack: myth_vs_truth) -->
    <section class="myth-truth wrap">
      <h2>Common myths and what we actually offer</h2>
      <div class="grid myths">
        <div class="card">
          <h3>Myth: It's mystical therapy</h3>
          <p>Truth: We deliver practical, evidence-informed experiences — tools you can use between sessions.</p>
        </div>
        <div class="card">
          <h3>Myth: You need to relax perfectly</h3>
          <p>Truth: Participants come as they are. The structure helps shift state incrementally.</p>
        </div>
        <div class="card">
          <h3>Myth: It replaces medical care</h3>
          <p>Truth: It's supportive adjunct practice. We include contraindications and encourage consultation when needed.</p>
        </div>
      </div>
    </section>

    <!-- Pillars (sectionPack: pillars) -->
    <section class="pillars wrap">
      <h2>Practice pillars — what we prioritize</h2>
      <div class="grid pillars-grid">
        <div class="pillar">
          <h4>Portable practices</h4>
          <p>Short patterns you can use at a desk, in an evening routine, or before sleep.</p>
        </div>
        <div class="pillar">
          <h4>Clear instructions</h4>
          <p>We name the technique, cue breath, and provide safety notes so you know what to expect.</p>
        </div>
        <div class="pillar">
          <h4>Series rhythm</h4>
          <p>Repeatable group formats that build familiarity and deeper effects over a few sessions.</p>
        </div>
      </div>

      <div class="pricing-comparator">
        <h3>Pricing at a glance</h3>
        <div class="toggle-row">
          <label class="switch">
            <input id="pricing-toggle" type="checkbox" aria-label="Toggle pricing view">
            <span class="slider"></span>
          </label>
          <span class="label-left">Monthly</span>
          <span class="label-right">Package</span>
        </div>

        <div class="tiers">
          <div class="tier" data-monthly="30" data-package="120">
            <strong class="tier-name">Pulse Pass</strong>
            <div class="price"><span class="num">$30</span><small class="unit">/mo</small></div>
            <p class="tier-desc">Monthly access to one weekly group and member notes.</p>
            <a class="tier-cta" href="/pricing.html">Choose</a>
          </div>

          <div class="tier" data-monthly="55" data-package="200">
            <strong class="tier-name">Resonant Duo</strong>
            <div class="price"><span class="num">$55</span><small class="unit">/mo</small></div>
            <p class="tier-desc">Two weekly sessions or one group + one private check-in per month.</p>
            <a class="tier-cta" href="/pricing.html">Choose</a>
          </div>

          <div class="tier" data-monthly="90" data-package="340">
            <strong class="tier-name">Tide Pass</strong>
            <div class="price"><span class="num">$90</span><small class="unit">/mo</small></div>
            <p class="tier-desc">Unlimited group access for consistent practice and deeper outcomes.</p>
            <a class="tier-cta" href="/pricing.html">Choose</a>
          </div>
        </div>
      </div>
    </section>

    <!-- Case notes (sectionPack: case_notes) -->
    <section class="case-notes wrap">
      <h2>Stories from the room</h2>
      <div class="grid case-grid">
        <article class="note">
          <p class="quote">"The short series helped me make a clear plan for mornings — not mystical, just quieter and sharper."</p>
          <p class="author">— A local teacher</p>
        </article>
        <article class="note">
          <p class="quote">"After a few sessions my sleep shifted. I kept the practice simple and it stuck."</p>
          <p class="author">— Community member</p>
        </article>
        <article class="note">
          <div class="mood-method" data-cta-template="{{PRIMARY_CTA_URL}}?mood={id}" data-cta-base="{{PRIMARY_CTA_URL}}">
            <label for="mood-case">Pick a state and see a tailored practice</label>
            <select id="mood-case" class="mood-select">
              <option value="calm">A little off-balance</option>
              <option value="wired">Edgy or wired</option>
              <option value="foggy">Distracted or foggy</option>
              <option value="flat">Tired or flat</option>
              <option value="celebrate">Want to deepen</option>
            </select>
            <div class="method-card">
              <strong class="method-title">Recommended: Short Alignment</strong>
              <p class="method-desc">A chair-based sequence with bell anchors and breath counts to bring focus fast.</p>
            </div>
            <div class="mood-cta-row">
              <a href="{{PRIMARY_CTA_URL}}" class="primary-cta">Book a session</a>
            </div>
          </div>
        </article>
      </div>
    </section>

    <!-- FAQ (sectionPack: faq) -->
    <section class="faq wrap">
      <h2>Helpful questions</h2>
      <details>
        <summary>What should I bring?</summary>
        <p>Comfortable clothing, a mat or blanket if you have one, and curiosity. We provide cushions and bolsters for communal sessions.</p>
      </details>
      <details>
        <summary>Contraindications?</summary>
        <p>Not suitable as a replacement for medical or psychiatric care. If you have epilepsy, recent head injuries, severe psychiatric conditions, are pregnant, or use pacemakers, consult a clinician before attending. If in doubt, reach out via {{EMAIL}} or call {{PHONE}}.</p>
      </details>
      <details>
        <summary>Will I fall asleep?</summary>
        <p>Some do, and that's fine. Others experience quiet alertness. Both are normal responses to practice.</p>
      </details>
    </section>

    <!-- CTA (sectionPack: cta) -->
    <section class="final-cta wrap">
      <h2>Ready to try a practical sound session?</h2>
      <p>Sign up for a single drop-in, book a private hour, or join a short series to anchor a new routine.</p>
      <div class="cta-row">
        <a class="primary-cta large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="secondary" href="/pricing.html">See membership & packages</a>
      </div>
      <p class="small-muted">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <nav class="footer-nav">
        <a href="/about.html">About</a>
        <a href="/faq.html">FAQ</a>
        <a href="/contact.html">Contact</a>
        <a href="/book.html">Book</a>
      </nav>
      <p class="muted">© <span id="year"></span> {{BUSINESS_NAME}} — Practical sound & session design</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
