{"path":"assets/css/styles.css","content":"/* Core styles — no external fonts or assets */
:root{
  --bg:#fbfbfb; --muted:#6b6b6b; --accent:#5a8cff; --accent-2:#6ac7c7; --card:#ffffff; --radius:12px; --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.4;background:var(--bg);color:#111}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.header-grid{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;text-decoration:none;color:#0b3550;font-size:1.1rem}
.nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.nav a{color:#0b3550;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:var(--accent);color:white}
.nav a.muted{color:var(--muted)}
.menu-toggle{display:none}
.hero{position:relative;overflow:hidden;padding:40px 0 60px;background:linear-gradient(180deg,#fff 0%,#f7fbff 100%)}
.pattern{position:absolute;inset:0;opacity:0.14;background-image:url('/assets/img/pattern.svg');background-repeat:repeat;background-size:320px}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:start}
.hero-copy h1{margin:0 0 12px;font-size:2rem;color:#07203a}
.lede{color:var(--muted);margin:0 0 18px}
.hero-aside{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(11,33,41,0.06)}
.next-event .when{font-size:0.9rem;color:var(--muted)}
.next-event h3{margin:6px 0}
.quick-stats{list-style:none;padding:0;margin:16px 0 0}
.quick-stats li{font-size:0.9rem;color:var(--muted);margin:8px 0}
.mood-method{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(0deg,rgba(90,140,255,0.06),transparent)}
.mood-select{width:100%;padding:8px;border-radius:8px;border:1px solid #e4eefb;margin:8px 0}
.method-card{padding:8px 6px}
.method-title{display:block;font-weight:700}
.mood-cta-row{display:flex;gap:10px;margin-top:8px}
.primary-cta{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none}
.secondary{background:transparent;border:1px solid #e5eefb;padding:10px 14px;border-radius:10px;color:var(--accent)}
.myth-truth{padding-top:20px}
.myths{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:12px}
.card{background:var(--card);padding:14px;border-radius:10px;box-shadow:0 6px 18px rgba(10,20,30,0.04)}
.pillars{padding-top:20px}
.pillars-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.pricing-comparator{margin-top:20px;background:linear-gradient(180deg,#fff,#f9feff);padding:14px;border-radius:12px}
.toggle-row{display:flex;align-items:center;gap:10px}
.switch{position:relative;display:inline-block;width:46px;height:26px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#e9f1ff;border-radius:999px}
.slider:before{content:"";position:absolute;height:20px;width:20px;left:3px;top:3px;background:white;border-radius:50%;transition:transform .25s ease}
.switch input:checked + .slider{background:linear-gradient(90deg,var(--accent),var(--accent-2))}
.switch input:checked + .slider:before{transform:translateX(20px)}
.tiers{display:flex;gap:12px;margin-top:12px}
.tier{background:var(--card);padding:14px;border-radius:10px;flex:1;box-shadow:0 6px 18px rgba(10,20,30,0.04)}
.tier .price{font-size:1.5rem;margin-top:6px}
.tier .unit{font-size:0.7rem;color:var(--muted);margin-left:6px}
.tier-cta{display:inline-block;margin-top:10px;padding:8px 12px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none}
.case-notes{padding-top:20px}
.case-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}
.note{background:var(--card);padding:12px;border-radius:10px}
.quote{font-style:italic}
.faq{padding-top:20px}
details{background:#fff;padding:10px;border-radius:10px;margin:8px 0}
.final-cta{padding:30px 14px;text-align:center;background:linear-gradient(180deg,#ffffff,#f1fbfa);border-radius:12px;margin:18px}
.cta-row{display:flex;gap:12px;justify-content:center;margin-top:12px}
.primary-cta.large{padding:14px 22px;font-size:1.05rem}
.site-footer{border-top:1px solid #eef6fb;padding:18px 0;margin-top:20px}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted)}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .myths,.pillars-grid,.tiers,.case-grid{grid-template-columns:1fr}
  .nav{display:none}
  .menu-toggle{display:block;margin-left:auto}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utility: animate number from start to end
  function animateNumber(el, from, to, duration){
    let start = null;
    const step = timestamp => {
      if (!start) start = timestamp;
      const progress = Math.min((timestamp - start)/duration,1);
      const value = Math.round(from + (to - from)*progress);
      el.textContent = '$'+value;
      if(progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  // Pricing comparator
  const pricingToggle = document.getElementById('pricing-toggle');
  const tiers = Array.from(document.querySelectorAll('.tier'));
  function updatePricing(usePackage){
    tiers.forEach(tier=>{
      const numEl = tier.querySelector('.num');
      const unitEl = tier.querySelector('.unit');
      const monthly = Number(tier.dataset.monthly);
      const pack = Number(tier.dataset.package);
      const from = parseInt((numEl.textContent||'$0').replace('$','')) || 0;
      const to = usePackage ? pack : monthly;
      // Animate
      animateNumber(numEl, from, to, 450);
      unitEl.textContent = usePackage ? '' : '/mo';
      // update CTA phrasing
      const cta = tier.querySelector('.tier-cta');
      cta.textContent = usePackage ? 'Buy package' : 'Subscribe';
    });
  }
  if(pricingToggle){
    pricingToggle.addEventListener('change', function(e){
      updatePricing(e.target.checked);
    });
    // initialize to monthly (unchecked)
    updatePricing(false);
  }

  // Mood-to-Method mapping
  const moodMap = {
    calm: {
      title: 'Gentle Resonance',
      desc: 'Long bowls and breath counts to ease subtle tension and invite clarity.',
      cta: 'Try a drop-in',
      id: 'calm'
    },
    wired: {
      title: 'Ground & Anchor',
      desc: 'Rhythmic vibro-mapping with firm breath cues to settle nervous energy.',
      cta: 'Book an anchor session',
      id: 'wired'
    },
    foggy: {
      title: 'Focus Bells',
      desc: 'Short bell anchors and guided posture shifts to cut through mental fog.',
      cta: 'Reserve a focus slot',
      id: 'foggy'
    },
    flat: {
      title: 'Slow Restore',
      desc: 'Lower tones and supportive cues designed to rebuild gentle metabolic energy.',
      cta: 'Schedule a private session',
      id: 'flat'
    },
    celebrate: {
      title: 'Deep Tides',
      desc: 'Layered harmonics and extended holds for deepening and refinement.',
      cta: 'Join the series',
      id: 'celebrate'
    }
  };

  // Attach to each .mood-method block
  document.querySelectorAll('.mood-method').forEach(block=>{
    const select = block.querySelector('.mood-select');
    const titleEl = block.querySelector('.method-title');
    const descEl = block.querySelector('.method-desc');
    const ctaEl = block.querySelector('.primary-cta');
    const template = block.dataset.ctaTemplate || '{{PRIMARY_CTA_URL}}';

    function applyMood(key){
      const info = moodMap[key] || moodMap['calm'];
      if(titleEl) titleEl.textContent = 'Recommended: '+info.title;
      if(descEl) descEl.textContent = info.desc;
      if(ctaEl){
        ctaEl.textContent = info.cta;
        // if template contains {id} replace, else set base
        if(template.indexOf('{id}')>-1){
          ctaEl.href = template.replace('{id}', info.id);
        } else {
          // append mood as query param
          const base = block.dataset.ctaBase || template;
          ctaEl.href = base + (base.indexOf('?')>-1 ? '&' : '?') + 'mood='+info.id;
        }
      }
    }

    if(select){
      select.addEventListener('change', function(e){
        applyMood(e.target.value);
      });
      // initialize
      applyMood(select.value || 'calm');
    }
  });

  // Small helpers
  // Set footer year
  const yearEl = document.getElementById('year'); if(yearEl) yearEl.textContent = new Date().getFullYear();

  // Simple mobile menu toggle
  const menuToggle = document.querySelector('.menu-toggle');
  const nav = document.querySelector('.nav');
  if(menuToggle && nav){
    menuToggle.addEventListener('click', function(){
      const open = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!open));
      nav.style.display = open ? 'none' : 'flex';
    });
  }

})();
"} 
